import{z as i,x as l,o as e,c as d,q as t,j as r,D as A,d as B,s,S as o,b as E}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"财报期策略","description":"","frontmatter":{"title":"财报期策略","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/earnings-season-strategies.md","filePath":"quant/earnings-season-strategies.md","lastUpdated":1791063341000}'),p={name:"quant/earnings-season-strategies.md"};function C(D,a,m,h,u,f){const n=l("Mermaid");return e(),d("div",null,[a[2]||(a[2]=t('<h1 id="财报期策略" tabindex="-1">财报期策略 <a class="header-anchor" href="#财报期策略" aria-label="Permalink to &quot;财报期策略&quot;">​</a></h1><div class="epigraph"><p>盈余公告把信息塞进一个狭窄窗口：漂移、公告溢价与交易量冲击叠在同一张日历上，却不是同一个可交易对象。</p><footer>—— 漂移见 Bernard and Thomas；公告溢价与成交见 Frazzini and Lamont, Journal of Financial Economics, 2007 前后文献</footer></div><p><a href="/quant/seasonality-anomalies">上一课</a>的时钟是市场日历。财报期的缺口是<strong>公司事件在季报季挤成一簇</strong>：预告、公告、电话会、指引。主干 <a href="/quant/pead-sue">PEAD</a>、<a href="/quant/event-study">事件研究</a> 已写识别与时间戳。<a href="/quant/event-driven-overview">事件驱动全景</a> 把 PEAD 标成漂移桶。本课给策略地图：公告前、公告瞬间、公告后如何分仓，避免把三种 P&amp;L 收成一个「财报因子」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Ball–Brown 以来，未预期盈余（SUE）后的漂移被反复测量。Bernard–Thomas 指出市场对序列相关的盈余反应不足。另一条线是公告日本身的溢价与成交：即使 SUE 接近零，暴露在公告上也可能有平均收益，并伴随冲击成本。问题是三套风险：(1) 公告前借券与信息泄漏边界；(2) 公告瞬间买卖价差与缺口；(3) 公告后 PEAD 的换手与衰减。回测若用公告日收盘价当成交，高估与事件研究课是同一错误。</p><p><span class="marginnote">「公告溢价」翻译一下：它不是稳赚的红包，而是市场为「公告惊吓」支付的风险补偿——像暴雨天送外卖多收的跑腿费：多数单子照收溢价，偶尔一单砸在手里。所以 SUE 接近零也可能有正的平均收益，代价是偶尔吃到大的负跳空。</span></p><p>与季节性：财报季与日历月相关，但不等于「四月效应」。应用公司自己的公告日对齐，而不是用月度虚拟变量。</p><h3 id="不要在公告前假装有公开边缘" tabindex="-1">不要在公告前假装有公开边缘 <a class="header-anchor" href="#不要在公告前假装有公开边缘" aria-label="Permalink to &quot;不要在公告前假装有公开边缘&quot;">​</a></h3><p>公开策略从公告时间戳之后开始。预告与分析师修订可以做成事件，但仍是公开信息。把未公开的仓位数据或窃听当「财报策略」不在本课范围。</p><p><span class="marginnote">拥挤的 PEAD 会把漂移前移到公告后第一小时。信号若仍用日频 SUE 隔日开盘买，吃到的是残渣加冲击。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分桶：公告前波动事件（仅公开日历）、公告日流动性供给、SUE/PEAD 截面、指引修正。每桶单独冲击模型。组合：单名跳跃限额；季报周的总 Gamma 与借券。对照：行业中性后的 PEAD 是否还在。容量按可借与公告日深度，不按全市场股票数。</p><p>四个桶各自的收益来源与主要约束：</p>',13)),(e(),r(o,null,{default:A(()=>[s(n,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20LR%0A%20%20B1%5B%22%E5%85%AC%E5%91%8A%E5%89%8D%E6%B3%A2%E5%8A%A8%E6%A1%B6%EF%BC%9A%E4%BB%85%E5%85%AC%E5%BC%80%E6%97%A5%E5%8E%86%E6%9A%B4%E9%9C%B2%22%5D%20--%3E%20C1%5B%22%E7%BA%A6%E6%9D%9F%EF%BC%9A%E6%97%A0%E5%86%85%E5%B9%95%E3%80%81%E5%80%9F%E5%88%B8%E8%B4%B9%E6%8C%89%E6%97%A5%22%5D%0A%20%20B2%5B%22%E5%85%AC%E5%91%8A%E6%97%A5%E6%B5%81%E5%8A%A8%E6%80%A7%E6%A1%B6%EF%BC%9A%E4%BE%9B%E7%BB%99%E4%BB%B7%E5%B7%AE%E4%B8%8E%E6%88%90%E4%BA%A4%22%5D%20--%3E%20C2%5B%22%E7%BA%A6%E6%9D%9F%EF%BC%9A%E7%BC%BA%E5%8F%A3%E6%96%B9%E5%90%91%E9%A3%8E%E9%99%A9%22%5D%0A%20%20B3%5B%22SUE%20%E6%BC%82%E7%A7%BB%E6%A1%B6%EF%BC%9APEAD%20%E6%88%AA%E9%9D%A2%22%5D%20--%3E%20C3%5B%22%E7%BA%A6%E6%9D%9F%EF%BC%9A%E5%86%B2%E5%87%BB%E6%88%90%E6%9C%AC%E4%B8%8E%E6%8B%A5%E6%8C%A4%E5%89%8D%E7%A7%BB%22%5D%0A%20%20B4%5B%22%E6%8C%87%E5%BC%95%E4%BF%AE%E6%AD%A3%E6%A1%B6%EF%BC%9A%E4%BF%AE%E6%AD%A3%E5%90%8E%E5%BB%B6%E7%BB%AD%22%5D%20--%3E%20C4%5B%22%E7%BA%A6%E6%9D%9F%EF%BC%9A%E4%B8%8E%E6%BC%82%E7%A7%BB%E6%A1%B6%E4%BF%A1%E5%8F%B7%E9%87%8D%E5%8F%A0%22%5D%0A%20%20ALL%5B%22%E5%9B%9B%E6%A1%B6%E5%88%86%E5%BC%80%E8%AE%B0%E8%B4%A6%E4%B8%8E%E9%99%90%E9%A2%9D%EF%BC%8C%E4%B8%8D%E5%90%88%E6%88%90%E4%B8%80%E4%B8%AA%E8%B4%A2%E6%8A%A5%E5%9B%A0%E5%AD%90%22%5D%0A%20%20C1%20--%3E%20ALL%0A%20%20C2%20--%3E%20ALL%0A%20%20C3%20--%3E%20ALL%0A%20%20C4%20--%3E%20ALL%0A"})]),fallback:A(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,[E("span",{class:"marginnote"},"为什么分桶记账重要：若把四桶合成一个「财报因子」，公告日一笔跳空亏损会抹掉漂移桶两个月的缓慢积累，你却看不出哪一桶失效。分开限额与归因，等于给每只桶单独装仪表盘。")],-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[B("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"公告把私人信息压缩释放。定价可以在方向上对、在速度上慢（漂移），也可以在风险上要求补偿（公告溢价）。灵活资本与做市商库存决定窗口有多短。财报期把许多名字的时钟对齐，相关升，事件驱动课里「平静期夏普」的警告在这里同样适用。",-1)),(e(),r(o,null,{default:A(()=>[s(n,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20Cal%5B%22%E5%85%AC%E5%91%8A%E6%97%A5%E5%8E%86%22%5D%20--%3E%20Pre%5B%22%E5%85%AC%E5%91%8A%E5%89%8D%20%E5%85%AC%E5%BC%80%E6%B3%A2%E5%8A%A8%22%5D%0A%20%20Cal%20--%3E%20Day%5B%22%E5%85%AC%E5%91%8A%E6%97%A5%20%E7%BC%BA%E5%8F%A3%E4%B8%8E%E5%86%B2%E5%87%BB%22%5D%0A%20%20Cal%20--%3E%20Post%5B%22SUE%20%E6%BC%82%E7%A7%BB%20PEAD%22%5D%0A%20%20Day%20--%3E%20Liq%5B%22%E6%B5%81%E5%8A%A8%E6%80%A7%E4%BE%9B%E7%BB%99%22%5D%0A%20%20Post%20--%3E%20Xs%5B%22%E6%88%AA%E9%9D%A2%E5%8F%AF%E7%B3%BB%E7%BB%9F%E5%8C%96%22%5D%0A"})]),fallback:A(()=>[...a[1]||(a[1]=[B(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>内幕与重大非公开信息是法律边界。电话会语言学、另类数据若用，必须可复现与合规。不要把分析师「偷偷提前」的故事写进回测。</p><p><span class="marginnote">常见误区：按持仓只数算分散。财报季里 50 只重仓股接连发财报，相关一起抬升、同涨同跌，账面波动远比「50 只股票」给人的直觉大——这正是季报周「分散被高估」的含义。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>财报策略按公告前、公告日、公告后分桶，不是一个因子。</li><li>时间戳与冲击决定 PEAD 是否还在。</li><li>季报周相关升高，分散被高估。</li><li>出处：Bernard and Thomas；Frazzini and Lamont 对公告溢价与成交的讨论；识别见事件研究课。</li></ul>',5))])}const c=i(p,[["render",C]]);export{P as __pageData,c as default};
